package com.fasterxml.jackson.core.base;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser.Feature;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.json.DupDetector;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.PackageVersion;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.core.util.TextBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for ParserBase.convertNumberToInt().
 * Since the method is protected, we use a Test subclass to expose it and set internal fields.
 */
public class ParserBase_convertNumberToInt_TriageGen2Test {

    // Constants mirrored from ParserBase for testing purposes
    private static final int NR_LONG = 1;
    private static final int NR_BIGINT = 2;
    private static final int NR_DOUBLE = 4;
    private static final int NR_BIGDECIMAL = 8;
    private static final int NR_INT = 16;

    private static final BigInteger BI_MIN_INT = BigInteger.valueOf(Integer.MIN_VALUE);
    private static final BigInteger BI_MAX_INT = BigInteger.valueOf(Integer.MAX_VALUE);
    private static final BigDecimal BD_MIN_INT = new BigDecimal(Integer.MIN_VALUE);
    private static final BigDecimal BD_MAX_INT = new BigDecimal(Integer.MAX_VALUE);
    private static final double MIN_INT_D = (double) Integer.MIN_VALUE;
    private static final double MAX_INT_D = (double) Integer.MAX_VALUE;

    private TestParserBase parser;

    @Before
    public void setUp() {
        parser = new TestParserBase(new IOContext(), 0);
    }

    /**
     * Test Case: NR_LONG branch - Lossless conversion
     */
    @Test
    public void testConvertLong_Lossless() throws IOException {
        parser._numTypesValid = NR_LONG;
        parser._numberLong = 12345L;
        parser.convertNumberToInt();
        assertEquals(12345, parser._numberInt);
        assertEquals(NR_LONG | NR_INT, parser._numTypesValid);
    }

    /**
     * Test Case: NR_LONG branch - Overflow (Lossy conversion)
     */
    @Test(expected = IOException.class)
    public void testConvertLong_Overflow() throws IOException {
        parser._numTypesValid = NR_LONG;
        parser._numberLong = (long) Integer.MAX_VALUE + 1L;
        parser.convertNumberToInt();
    }

    /**
     * Test Case: NR_BIGINT branch - Valid range
     */
    @Test
    public void testConvertBigInt_Valid() throws IOException {
        parser._numTypesValid = NR_BIGINT;
        parser._numberBigInt = BigInteger.valueOf(Integer.MAX_VALUE);
        parser.convertNumberToInt();
        assertEquals(Integer.MAX_VALUE, parser._numberInt);
    }

    /**
     * Test Case: NR_BIGINT branch - Overflow
     */
    @Test(expected = IOException.class)
    public void testConvertBigInt_Overflow() throws IOException {
        parser._numTypesValid = NR_BIGINT;
        parser._numberBigInt = BigInteger.valueOf(Integer.MAX_VALUE).add(BigInteger.ONE);
        parser.convertNumberToInt();
    }

    /**
     * Test Case: NR_DOUBLE branch - Valid range
     */
    @Test
    public void testConvertDouble_Valid() throws IOException {
        parser._numTypesValid = NR_DOUBLE;
        parser._numberDouble = 123.45;
        parser.convertNumberToInt();
        assertEquals(123, parser._numberInt);
    }

    /**
     * Test Case: NR_DOUBLE branch - Overflow
     */
    @Test(expected = IOException.class)
    public void testConvertDouble_Overflow() throws IOException {
        parser._numTypesValid = NR_DOUBLE;
        parser._numberDouble = MAX_INT_D + 1.0;
        parser.convertNumberToInt();
    }

    /**
     * Test Case: NR_BIGDECIMAL branch - Valid range
     */
    @Test
    public void testConvertBigDecimal_Valid() throws IOException {
        parser._numTypesValid = NR_BIGDECIMAL;
        parser._numberBigDecimal = new BigDecimal("100.5");
        parser.convertNumberToInt();
        assertEquals(100, parser._numberInt);
    }

    /**
     * Test Case: NR_BIGDECIMAL branch - Overflow
     */
    @Test(expected = IOException.class)
    public void testConvertBigDecimal_Overflow() throws IOException {
        parser._numTypesValid = NR_BIGDECIMAL;
        parser._numberBigDecimal = new BigDecimal(Integer.MAX_VALUE).add(BigDecimal.ONE);
        parser.convertNumberToInt();
    }

    /**
     * Test Case: No valid type - Should trigger _throwInternal
     */
    @Test(expected = IOException.class)
    public void testConvert_NoValidType() throws IOException {
        parser._numTypesValid = 0;
        parser.convertNumberToInt();
    }

    /**
     * Test Subclass to access and manipulate protected members of ParserBase.
     */
    private static class TestParserBase extends ParserBase {
        int _numTypesValid;
        long _numberLong;
        BigInteger _numberBigInt;
        double _numberDouble;
        BigDecimal _numberBigDecimal;
        int _numberInt;
        String _text = "123";

        protected TestParserBase(IOContext ctxt, int features) {
            super(ctxt, features);
        }

        @Override
        protected void _closeInput() throws IOException {}

        @Override
        protected void _releaseBuffers() throws IOException {}

        @Override
        protected void _handleEOF() throws com.fasterxml.jackson.core.JsonParseException {
            throw new com.fasterxml.jackson.core.JsonParseException(null, "EOF");
        }

        @Override
        protected void _throwInternal() throws IOException {
            throw new IOException("Internal Error");
        }

        @Override
        protected void _reportError(String msg) throws IOException {
            throw new IOException(msg);
        }

        @Override
        protected void reportOverflowInt() throws IOException {
            throw new IOException("Overflow");
        }

        @Override
        protected String getText() {
            return _text;
        }

        // Expose the protected method for testing
        @Override
        protected void convertNumberToInt() throws IOException {
            super.convertNumberToInt();
        }
    }
}
